export interface ClickParams {
  /**
   * Snapshot the reference was issued by.
   */
  readonly snapshot_id: Identifier;
  /**
   * Element reference from that snapshot.
   */
  readonly ref: ElementReference;
}

/**
 * Input for type_text. Secret values MUST NOT be supplied here (docs/MCP_SPEC.md section
 * 7.4).
 */
export interface TypeTextParams {
  /**
   * Snapshot the reference was issued by.
   */
  readonly snapshot_id: Identifier;
  /**
   * Element reference from that snapshot.
   */
  readonly ref: ElementReference;
  /**
   * Text to type.
   */
  readonly text: InputText;
  /**
   * Whether to press Enter after typing.
   */
  readonly submit?: boolean;
}

/**
 * Input for resize. A resize invalidates every outstanding element reference
 * (docs/MCP_SPEC.md section 7.4).
 */
export interface ResizeParams {
  /**
   * New viewport.
   */
  readonly viewport: Viewport;
}

/**
 * Input for wait. Every condition is bounded; there is no unbounded sleep.
 */
export interface WaitParams {
  /**
   * Condition to wait for.
   */
  readonly condition: WaitCondition;
  /**
   * Substring the URL must contain.
   */
  readonly url_pattern?: UrlPattern;
  /**
   * Selector whose state is awaited.
   */
  readonly selector?: Selector;
  /**
   * Text whose presence is awaited.
   */
  readonly text?: PageText;
}

/**
 * Input for snapshot. Both bounds are optional; the session limits supply the defaults.
 */
export interface SnapshotParams {
  /**
   * Largest number of elements to describe.
   */
  readonly max_nodes?: number;
  /**
   * Largest rendered snapshot to return before truncation.
   */
  readonly max_bytes?: number;
}

/**
 * Input for take_screenshot (docs/MCP_SPEC.md section 7.4).
 */
export interface ScreenshotParams {
  /**
   * Whether to capture beyond the viewport.
   */
  readonly full_page: boolean;
  /**
   * Whether to upload the capture through the control-plane artefact API. A capture that
   * is not persisted produces no artefact and no evidence.
   */
  readonly persist: boolean;
  /**
   * Why the capture is being taken.
   */
  readonly purpose: ScreenshotPurpose;
}

/**
 * One browser command. Exactly one parameter object accompanies the command name; the
 * schema forbids the others so a command cannot smuggle an unused parameter set.
 */
export interface BrowserCommand {
  /**
   * Command to run.
   */
  readonly command: CommandName;
  /**
   * Bound on how long the command may run. Exceeding it fails with BROWSER_COMMAND_TIMEOUT
   * rather than waiting indefinitely.
   */
  readonly timeout_ms: number;
  /**
   * Parameters for navigate.
   */
  readonly navigate?: NavigateParams;
  /**
   * Parameters for click.
   */
  readonly click?: ClickParams;
  /**
   * Parameters for type_text.
   */
  readonly type_text?: TypeTextParams;
  /**
   * Parameters for resize.
   */
  readonly resize?: ResizeParams;
  /**
   * Parameters for wait.
   */
  readonly wait?: WaitParams;
  /**
   * Parameters for snapshot.
   */
  readonly snapshot?: SnapshotParams;
  /**
   * Parameters for take_screenshot.
   */
  readonly take_screenshot?: ScreenshotParams;
}

/**
 * A refused or failed operation, reported with a stable code (docs/MCP_SPEC.md section
 * 12).
 */
export interface CommandError {
  /**
   * Stable error class.
   */
  readonly code: ErrorClass;
  /**
   * Operator-facing explanation. Carries no credentials and no unbounded page content.
   */
  readonly message: ReasonText;
  /**
   * Whether retrying the same command could succeed.
   */
  readonly retryable: boolean;
  /**
   * Epoch that is actually current, returned with CONTROL_EPOCH_STALE so the caller can
   * refresh rather than guess (docs/MCP_SPEC.md section 5).
   */
  readonly current_epoch?: number;
}

/**
 * Outcome of a navigation. Every field is page-derived and therefore untrusted.
 */
export interface NavigationResult {
  /**
   * URL the browser settled on.
   */
  readonly url: ResolvedUrl;
  /**
   * Status of the main document response.
   */
  readonly http_status?: number;
  /**
   * Whether the browser settled on a different URL than requested.
   */
  readonly redirected: boolean;
  /**
   * Document title, truncated to its bound.
   */
  readonly title: PageText;
}

/**
 * One element of a snapshot, addressable by reference until the snapshot is superseded.
 */
export interface ElementDescriptor {
  /**
   * Reference valid for this snapshot only.
   */
  readonly ref: ElementReference;
  /**
   * Accessibility role.
   */
  readonly role: AccessibleRole;
  /**
   * Accessible name, truncated to its bound.
   */
  readonly name?: PageText;
}

/**
 * A bounded accessibility snapshot (docs/MCP_SPEC.md sections 7.4 and 13). Page-derived
 * throughout.
 */
export interface SnapshotResult {
  /**
   * Identity of this snapshot. A reference is accepted only while it is the current
   * snapshot.
   */
  readonly snapshot_id: Identifier;
  /**
   * Viewport the snapshot was taken at. A resize supersedes it.
   */
  readonly viewport: Viewport;
  /**
   * Number of elements described.
   */
  readonly node_count: number;
  /**
   * Whether the page had more content than the bounds allowed. A truncated snapshot is a
   * summary, never a whole-page dump.
   */
  readonly truncated: boolean;
  /**
   * Rendered snapshot.
   */
  readonly text: SnapshotText;
  /**
   * Machine-readable form of the same elements.
   */
  readonly elements: readonly ElementDescriptor[];
}

/**
 * A screenshot that the control plane has verified and made available (docs/API.md section
 * 15, ADR-0012).
 */
export interface ScreenshotResult {
  /**
   * Artefact the capture was stored as. Present only once the control plane has verified
   * size and hash.
   */
  readonly artefact_id: Identifier;
  /**
   * Digest the control plane verified.
   */
  readonly sha256: Sha256Hex;
  /**
   * Byte length the control plane verified.
   */
  readonly size_bytes: number;
  /**
   * Media type of the stored bytes.
   */
  readonly content_type: ImageContentType;
  /**
   * Viewport the capture was taken at.
   */
  readonly viewport: Viewport;
  /**
   * Whether the capture extends beyond the viewport.
   */
  readonly full_page: boolean;
  /**
   * When the capture was taken.
   */
  readonly captured_at: Timestamp;
}

/**
 * Result of one browser command. The trust rules below are enforced by the generated
 * validators on both sides, so page-derived content cannot be returned without its
 * untrusted label (ADR-0010).
 */
export interface BrowserCommandResult {
  /**
   * Whether the command succeeded.
   */
  readonly ok: boolean;
  /**
   * Command this result answers.
   */
  readonly command: CommandName;
  /**
   * Sequence number of the command this result answers.
   */
  readonly sequence: number;
  /**
   * Epoch current at the worker when the command ran.
   */
  readonly control_epoch: number;
  /**
   * How long the command took.
   */
  readonly duration_ms: number;
  /**
   * Trust of the content in this result.
   */
  readonly trust: TrustLabel;
  /**
   * How the receiver must treat that content.
   */
  readonly instruction_policy: InstructionPolicy;
  /**
   * Why the command failed.
   */
  readonly error?: CommandError;
  /**
   * Navigation outcome. Page-derived.
   */
  readonly navigation?: NavigationResult;
  /**
   * Accessibility snapshot. Page-derived.
   */
  readonly snapshot?: SnapshotResult;
  /**
   * Verified screenshot artefact. Rendered from page content.
   */
  readonly screenshot?: ScreenshotResult;
  /**
   * Viewport in force after the command.
   */
  readonly viewport?: Viewport;
}

/**
 * A decoded control frame: envelope header plus the payload selected by its type.
 */
export type BrowserFrame =
  | {
      readonly envelope: Envelope;
      readonly type: "worker.register";
      readonly payload: WorkerRegistration;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "worker.register.ack";
      readonly payload: WorkerRegistrationAck;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "worker.heartbeat";
      readonly payload: WorkerHeartbeat;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "browser_session.allocate";
      readonly payload: SessionAllocate;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "browser_session.allocated";
      readonly payload: SessionAllocated;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "browser_session.status";
      readonly payload: SessionStatusReport;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "browser_session.terminate";
      readonly payload: SessionTerminate;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "browser.command";
      readonly payload: BrowserCommand;
    }
  | {
      readonly envelope: Envelope;
      readonly type: "browser.command.result";
      readonly payload: BrowserCommandResult;
    }
;
